export function GuillocheContainer({ style, className, ...props }: HTMLProps<HTMLDivElement>) {
    return <div 
    className={`${className} @lg/badge:max-w-18`}
    style={{
        overflow: "hidden",
        position: "relative",
    }} 
    {...props} 
    />
}

export function Guilloche({ style, ...props }: HTMLProps<HTMLDivElement>) {
    return <div style={{
        ...style,
        minWidth: '142%',
        minHeight: '142%',
        aspectRatio: '1/1',
        position: "absolute",
        left: "50%",
        top: "50%",
        transform: "translateX(-50%) translateY(-50%)",
        transformOrigin: "center",
        backgroundSize: "40px",
        backgroundImage: guillocheSvgUrl,
    }} {...props} />
}

export function MaskedGuilloche({style, ...props}: HTMLProps<HTMLDivElement>) {
    return <div style={{
        minWidth: '142%',
        minHeight: '142%',
        aspectRatio: '1/1',
        position: "absolute",
        left: "50%",
        top: "50%",
        transform: "translateX(-50%) translateY(-50%)",
        transformOrigin: "center",
        maskSize: "40px",
        ...style,
        maskImage: guillocheSvgUrl,
    }} {...props} />
}